        go func() {
                scanner := bufio.NewScanner(stdout)
                for scanner.Scan() {
                        line := strings.TrimSpace(scanner.Text())
                        if line != "" {
                                if len(line) > 150 {
                                        line = line[:147] + "..."
                                }
                                logMsg := fmt.Sprintf("[%s] %s", time.Now().Format("15:04:05"), line)
                                c.pipelineLogChan <- PipelineLogMsg{
